True def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                top, left = r - 2, c - 2
                if 0 <= top < h:
                    for x in range(left, left + 5):
                        if 0 <= x < w:
                            out[top][x] = 5
                for y in range(r - 1, r + 2):
                    for x in (c - 2, c + 2):
                        if 0 <= y < h and 0 <= x < w:
                            out[y][x] = 2
                out[r - 1][c] = 5
                out[r][c] = 3
                bottom = r + 2
                if 0 <= bottom < h:
                    out[bottom] = [2] * w
                    for x in range(max(0, c - 2), min(w, c + 3)):
                        out[bottom][x] = 8
    return out
